cases.candidate_script:
[[ $(type -t xargs) == builtin ]] || exit 125
for mode in normal replace parallel empty; do
  case $mode in
    normal) args=(-p -n 1); input=yes;;
    replace) args=(-p -I X); input=yes;;
    parallel) args=(-p -P 2 -n 1); input=yes;;
    empty) args=(-p); input=;;
  esac
  if [[ $mode == empty ]]; then printf '' >input; else printf '%s\n' "$input" >input; fi
  /usr/bin/setsid -w "$BASH" --noprofile --norc -c '[[ $(type -t xargs) == builtin ]] || exit 125; xargs "$@" /usr/bin/printf "CHILD:%s\n"' _ "${args[@]}" <input >out 2>err
  s=$?
  [[ $s == 1 && ! -s out ]] || { printf 'failure %s status=%s\n' "$mode" "$s"; exit 1; }
  /usr/bin/grep -q '/dev/tty' err || { printf 'missing diagnostic %s\n' "$mode"; exit 1; }
done
printf 'no-tty rejected\n'
